CREATE VIEW dq_playability_enrichment_priority AS SELECT p.GameKey, p.GameID, p.GameTitle, p.final_recommendation_score, p.playability_status, p.recommendation_status, CASE  WHEN ((p.final_recommendation_score >= 95)) THEN ('Priority 1') WHEN ((p.final_recommendation_score >= 90)) THEN ('Priority 2') WHEN ((p.final_recommendation_score >= 80)) THEN ('Priority 3') ELSE 'Lower Priority' END AS enrichment_priority FROM mart_play_next_v2 AS p WHERE (p.playability_status = 'Unknown') ORDER BY p.final_recommendation_score DESC, p.GameTitle;
